ORIGINAL_SOURCE_ITEM = shared.source_item


def tafheem_group(verse: int) -> tuple[str, str]:
    if verse <= 50:
        return "43–50", "۴:۴۳–۵۰"
    if verse <= 56:
        return "51–56", "۴:۵۱–۵۶"
    return "57–70", "۴:۵۷–۷۰"


def scoped_source_item(source_id: str, verse: int, text: str) -> dict:
    if source_id == FAYRUZ_ID:
        return {
            "text": text,
            "cite": "فیروزآبادی، ۸۱۷ق، *تفسير القرآن*، شرحِ گروهیِ نساء ۴:۴۸–۵۴، ذیلِ ۴:۵۲؛ GreatTafsirs؛ چاپ/صفحهٔ کتاب احراز نشده.",
            "kind": "source-summary",
            "language": "fa",
            "sourceId": FAYRUZ_ID,
            "sourceUrl": FAYRUZ_URL,
            "evidence": "موضعِ بررسی: صفحهٔ گروهیِ واقعیِ ۴:۴۸–۵۴ در GreatTafsirs؛ متنِ ۴:۵۲ در همان صفحه مقابله شد.",
            "limit": shared.SOURCE_LIMIT,
            "tradition": "اهل‌سنت",
        }

    result = ORIGINAL_SOURCE_ITEM(source_id, verse, text)
    if source_id == "en_tafheem_ul_quran":
        key, group_label = tafheem_group(verse)
        result["sourceUrl"] = TAFHEEM_GROUPS[key]
        if verse == 60:
            detail = "یادداشتِ ۹۱ خوانده شد؛ تفسیرِ نظامِ قضایی به مودودی منسوب است."
        elif verse == 59:
            detail = "یادداشت‌های ۸۹–۹۰ خوانده شدند؛ تفسیرِ سیاسی به مودودی منسوب است."
        elif verse == 51:
            detail = "یادداشتِ ۸۱ ذیلِ آیه مقابله شد."
        elif verse == 54:
            detail = "یادداشت‌های ۸۵–۸۷ ذیلِ حسد و ملک مقابله شدند."
        else:
            detail = "ترجمهٔ آیه در صفحه مقابله شد؛ یادداشتِ شماره‌دارِ دیگری در این بند ادعا نمی‌شود."
        result["cite"] = (
            f"مودودی، *تفہيم القرآن*، ذیلِ نساء ۴:{verse}؛ "
            f"صفحهٔ گروهیِ واقعیِ {group_label}؛ {detail}"
        )
        result["evidence"] = (
            f"موضعِ بررسی: شرحِ گروهیِ واقعیِ {group_label}؛ متنِ ترجمه و یادداشتِ موجود برای آیه مقابله شد."
        )
    elif source_id == "ar_fayd_safi":
        page_verse, group_label = FAYD_GROUPS[verse]
        result["sourceUrl"] = shared.SOURCE_META[source_id]["url"].format(verse=page_verse)
        result["cite"] = (
            f"فیض کاشانی، ۱۰۹۰ق، *الصافي في تفسير كلام الله الوافي*، "
            f"شرحِ گروهی/آیه‌محورِ نساء {group_label}؛ GreatTafsirs؛ چاپ/صفحهٔ کتاب احراز نشده."
        )
        result["evidence"] = (
            f"موضعِ بررسی: صفحهٔ مستقیمِ GreatTafsirs برای {group_label}؛ حدودِ آیات با سرعنوان و متن مقابله شد."
        )
    elif source_id in {"ar_tabari_qurancom", "ar_ibn_kathir_qurancom"}:
        result["evidence"] = (
            f"موضعِ بررسی: مدخلِ عربیِ نساء ۴:{verse} در آرشیوِ ثابتِ نسخهٔ ۱٫۱؛ "
            "SHA-256 با رجیستری مقابله شد و پیوندِ آیه‌محور نیز ثبت است."
        )
    elif source_id == "ar_jalalayn_qurancom":
        result["evidence"] = f"موضعِ بررسی: صفحهٔ مستقیمِ جلالین برای نساء ۴:{verse}؛ خلاصه به همان آیه پیوند دارد."
    elif source_id == "ar_tusi_tibyan":
        result["evidence"] = f"موضعِ بررسی: صفحهٔ مستقیمِ التبيان برای نساء ۴:{verse} در GreatTafsirs؛ چاپ و صفحهٔ کتاب احراز نشده است."
    elif source_id == "ar_qe_arabic_moyassar":
        result["evidence"] = f"موضعِ بررسی: متنِ محلیِ QuranEnc، التفسير الميسر، نساء ۴:{verse}؛ نسخهٔ ۱٫۰٫۰ در رجیستری ثبت است."
    return result


